SELECT IF((SELECT COUNT(*) FROM abt_variabel WHERE no_var IN (4850,4851,4852,4853,4854,4855,4856,4857,4858,4860,4861,4862,4863,4864,4880,4881,4882,4883,4884,4885,4886,4887,4888,4889,4890,4891,4892,4893,4894,4895,4896,4897,4898,4899,4900,4901,4902,4903,4904,4905,4906,4907,4908,4909,4910,4911,4912,4913,4914,4915,4916,4917,4918,4919,4920,4921,4922,4923,4924,4925,4930,4931,4932,4933,4934,4935,4936,4937,4938,4939))=0, 'PULIH COCOK', CONCAT('PULIH TIDAK LENGKAP - variabel baru yang masih ada ', (SELECT COUNT(*) FROM abt_variabel WHERE no_var IN (4850,4851,4852,4853,4854,4855,4856,4857,4858,4860,4861,4862,4863,4864,4880,4881,4882,4883,4884,4885,4886,4887,4888,4889,4890,4891,4892,4893,4894,4895,4896,4897,4898,4899,4900,4901,4902,4903,4904,4905,4906,4907,4908,4909,4910,4911,4912,4913,4914,4915,4916,4917,4918,4919,4920,4921,4922,4923,4924,4925,4930,4931,4932,4933,4934,4935,4936,4937,4938,4939)), ' (diubah orang sesudah dipasang? dibiarkan)')) AS hasil;
